    "Unlisted" : "Nicht aufgelistet",
    "Direct" : "Direkt",
    "Your posts do best around {hour}:00 UTC — {n} engagement each, over {posts} posts." : "Deine Beiträge kommen gegen {hour}:00 UTC am besten an: {n} Interaktionen pro Beitrag bei {posts} Beiträgen.",
    "Boosts of other people" : "Boosts anderer",
    "Counted over your {count} most recent posts, which is as far back as this page goes." : "Berechnet anhand deiner {count} neuesten Beiträge. Weiter reichen die Daten auf dieser Seite nicht zurück.",
    "_Counted over your one post._::_Counted over all {count} of your posts._" : ["Für deinen einzigen Beitrag berechnet.","Für alle {count} deiner Beiträge berechnet."],
    "Could not work out your statistics." : "Deine Statistiken konnten nicht berechnet werden.",
    "Could not download your statistics" : "Ihre Statistiken konnten nicht heruntergeladen werden",
    "new" : "neu",
    "_%n engagement in {month}_::_%n engagement in {month}_" : ["%n Interaktion im {month}","%n Interaktionen im {month}"],
    "_%n follower in {month}_::_%n followers in {month}_" : ["%n Follower im {month}","%n Follower im {month}"],
